'use strict';
const KEY='toolbox-voyage-ready-v1';
const defaults={requirements:[['STCW Basic Safety Training',false],['Medical Certificate (PEME)',false],['Company-required training',false],['Passport validity',false],['Visa (if applicable)',false],['Joining instructions',false]],packing:[['Toothbrush',1],['Toothpaste',3],['Soap',6],['Shampoo',2],['Deodorant',2],['Socks',10]],embarkation:[['Flight itinerary',false],['Joining instructions',false],['Passport',false],['Seaman’s book',false],['Medical certificate',false]],disembarkation:[['Sea service certificate',false],['Crew appraisal',false],['Sign-off clearance',false],['Return flight details',false]]};
const state={tab:'home',page:'home',voyage:load()};
function load(){try{return JSON.parse(localStorage.getItem(KEY))}catch{return null}}
function save(){localStorage.setItem(KEY,JSON.stringify(state.voyage));}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function progress(items){if(!items?.length)return 0;const applicable=items.filter(x=>!x.na);return applicable.length?Math.round(applicable.filter(x=>x.done).length/applicable.length*100):100;}
function ring(n){return `<div class="ring" style="--pct:${n}" data-pct="${n}%" aria-label="${n}% complete"></div>`}
function navigate(page){state.page=page;render();window.scrollTo(0,0)}
function sectionRow(id,label){const p=state.voyage;return `<div class="row" role="button" tabindex="0" data-open="${id}"><span style="font-size:24px;color:#007454">${{requirements:'▤',packing:'▣',embarkation:'✈',disembarkation:'⚑'}[id]}</span><span class="grow"><b>${label}</b><div class="muted">${p[id].filter(x=>x.done).length} of ${p[id].length} completed</div></span>${ring(progress(p[id]))}<span>›</span></div>`}
const serviceGroups=[
 {title:'Maritime Services',items:[['MARINA','⚓','https://marina.gov.ph'],['MISMO','▣',null],['Online Appointment','▦',null]]},
 {title:'PEME Clinics',items:[['SuperCare','✚',null],['YGEIA','✚',null],['Nordic','✚',null]]},
 {title:'OFW Services',items:[['DMW','▤','https://dmw.gov.ph'],['OWWA','✦','https://owwa.gov.ph'],['PhilHealth','✚','https://www.philhealth.gov.ph'],['SSS','▥','https://www.sss.gov.ph'],['Pag-IBIG','⌂','https://www.pagibigfund.gov.ph'],['OFBank','₱',null]]},
 {title:'Training Centers',items:[['CREST','⚙',null],['EXACT','⚙',null]]},
 {title:'Manning Agencies',items:[['Pascor','⚓',null],['Capital Shipping','⚓',null],['BSM','⚓',null],['JPhil','⚓',null],['Knutsen','⚓',null]]},
 {title:'Document Services',items:[['Passport','▣','https://www.passport.gov.ph'],['NBI Clearance','▤','https://clearance.nbi.gov.ph'],['PSA','▥','https://psa.gov.ph']]}];
const categoryIcons=['⚓','✚','◉','🎓','🚢','▣'];
function servicesMarkup(){return `<div class="directory-heading"><h2>Seafarer Services</h2><span class="muted">Swipe to explore →</span></div><div class="category-scroll" aria-label="Service categories">${serviceGroups.map((g,gi)=>`<button class="category-tile" data-directory="${gi}" aria-label="Open ${escapeHTML(g.title)}"><span class="category-icon color-${gi}">${categoryIcons[gi]}</span><span class="category-name">${escapeHTML(g.title)}</span></button>`).join('')}</div>`}
function directoryPage(gi){const g=serviceGroups[gi];if(!g)return home();return `<button class="back" data-open="home">← Home</button><div class="service-page-banner"><span class="service-page-symbol">${categoryIcons[gi]}</span><h1>${escapeHTML(g.title)}</h1><p>Find services and official portals</p></div><div class="search-wrap directory-search"><span aria-hidden="true">⌕</span><input id="directorySearch" placeholder="Search ${escapeHTML(g.title)}..." aria-label="Search ${escapeHTML(g.title)}"></div><div class="service-list">${g.items.map(([name,icon,url],i)=>`<button class="service-list-card" data-service="${gi}:${i}"><span class="service-list-icon color-${gi}">${icon}</span><span class="service-list-copy"><strong>${escapeHTML(name)}</strong><small>${url?'Open service website':'Website verification pending'}</small></span><span class="service-list-arrow">›</span></button>`).join('')}</div><p class="directory-disclaimer">Toolbox is independent and not affiliated with these providers. Verify service details with the provider.</p>`}
function serviceDialog(gi,idx){const group=serviceGroups[gi], item=group?.items[idx];if(!item)return;const [name,,url]=item;openModal(`<h2>${escapeHTML(name)}</h2><p class="muted">${escapeHTML(group.title)}</p>${url?`<p>Open the service website in a new tab. Confirm the current service details directly with the provider.</p><a class="btn full service-link" href="${url}" target="_blank" rel="noopener noreferrer">Open website ↗</a>`:`<p>This provider's official direct link has not yet been verified. We will add it after checking the correct website.</p><button class="btn secondary full" type="button" disabled>Link pending verification</button>`}`)}
function safeLocal(key){try{return JSON.parse(localStorage.getItem(key))}catch{return null}}
function dashboardCards(){
 // No fabricated metrics: the legacy app's exam and document stores are not integrated yet.
 const exams=safeLocal('toolbox2-exam-summary');
 const docs=safeLocal('toolbox2-document-summary');
 const examValid=exams&&Number.isFinite(exams.average)&&Number.isFinite(exams.attempts)&&exams.attempts>0;
 const docValid=docs&&Number.isFinite(docs.expiring)&&Number.isFinite(docs.expired);
 return `<section class="dashboard-section"><div class="section-title"><h2>Your Dashboard</h2></div><div class="dashboard-grid"><button class="metric-card exam" data-open="learn" aria-label="Open exam performance"><span class="metric-icon">▤</span><span class="metric-label">EXAM PERFORMANCE</span><strong class="metric-number">${examValid?`${Math.round(exams.average)}%`:'—'}</strong><span class="metric-description">${examValid?`${exams.attempts} exams taken`:'No linked exam results yet'}</span><span class="metric-action">View Results ›</span></button><button class="metric-card documents" data-open="documents" aria-label="Open document status"><span class="metric-icon">▣</span><span class="metric-label">DOCUMENT STATUS</span><strong class="metric-number">${docValid?docs.expiring:'—'}</strong><span class="metric-description">${docValid?`Expiring soon · ${docs.expired} expired`:'Connect document records'}</span><span class="metric-action">Review Documents ›</span></button></div></section>`;
}
function continueSection(){const p=state.voyage;return `<section class="resume-section"><div class="section-title"><h2>Continue Where You Left Off</h2></div>${p?`<button class="resume-card" data-open="voyage"><span class="resume-symbol">⚓</span><span class="grow"><b>Voyage Ready</b><small>${escapeHTML(p.vessel)} · Continue checklist</small></span>${ring(Math.round((progress(p.requirements)+progress(p.packing)+progress(p.embarkation))/3))}<span class="chevron">›</span></button>`:`<div class="card resume-empty"><b>Ready for your next voyage?</b><p class="muted">Create your first contract checklist to pick up where you left off.</p><button class="btn secondary" data-open="voyage">Get Started →</button></div>`}<button class="resume-card" data-open="learn"><span class="resume-symbol learn">▤</span><span class="grow"><b>OIC Review & OLP</b><small>Open your learning modules</small></span><span class="chevron">›</span></button></section>`}
function ecosystemAndRating(){const rating=Number(localStorage.getItem('toolbox2-feedback-rating'))||0;return `<section class="ecosystem-card"><span class="ecosystem-kicker">BULLETPROOF SEAFARER</span><h2>Three Apps. One Crew.</h2><p>Your Seafaring Life. In Your Pocket.</p><div class="ecosystem-apps"><span>Quebec Fit</span><span>Project Gangway</span><span>Toolbox</span></div><strong class="coming-soon">Ecosystem access · Coming Soon</strong></section><section class="rating-card"><div class="rating-symbol">♡</div><div><h2>Enjoying Toolbox?</h2><p>Help us build a better maritime companion.</p></div><div class="rating-stars" role="group" aria-label="Rate Toolbox from 1 to 5">${[1,2,3,4,5].map(n=>`<button data-rating="${n}" aria-label="Rate ${n} out of 5" aria-pressed="${n===rating}">${n<=rating?'★':'☆'}</button>`).join('')}</div><small>${rating?'Thanks for your feedback!':'Tap a star to save your rating on this device.'}</small></section>`}
function home(){const p=state.voyage;const percent=p?Math.round((progress(p.requirements)+progress(p.packing)+progress(p.embarkation))/3):0;return `<section class="home-banner"><div class="greeting"><span>Good day,</span><h1>Seafarer!</h1><p>Your Maritime Companion</p></div><img class="home-mascot" src="assets/toolbox-spanner.png" alt="Toolbox wrench mascot" onerror="this.src='assets/seafarer-mascot.webp'"></section><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" placeholder="Search services, documents, learning..." aria-label="Search Toolbox"></div><div class="card hero voyage-card"><div class="hero-top"><div class="grow"><h2>Voyage Ready</h2><p class="muted">Prepare for your next contract</p><p class="voyage-count">⚓ ${p?`${p.requirements.filter(x=>x.done).length+p.packing.filter(x=>x.done).length+p.embarkation.filter(x=>x.done).length} tasks completed`:'Your next contract starts here'}</p></div>${ring(percent)}</div><button class="btn full lime" data-open="voyage">${p?'Continue Checklist':'Prepare for My Next Contract'} →</button></div>${servicesMarkup()}${dashboardCards()}${continueSection()}${ecosystemAndRating()}<footer>Developed by Bulletproof Seafarer<br>Independent tool · Not a government service</footer>`}

function voyage(){const p=state.voyage;if(!p)return `<button class="back" data-open="home">← Home</button><h1>Voyage Ready</h1><p class="muted">Prepare for your next contract with checklists you control.</p><div class="card"><label class="field">Vessel name<input id="vessel" placeholder="e.g. MV Explorer"></label><label class="field">Joining date<input id="joining" type="date"></label><label class="field">Contract duration <span id="monthsLabel">6 months</span><input id="months" type="range" min="1" max="12" value="6"></label><button class="btn full" id="startVoyage">Create My Voyage</button></div>`;const overall=Math.round((progress(p.requirements)+progress(p.packing)+progress(p.embarkation))/3);return `<button class="back" data-open="home">← Home</button><h1>Voyage Ready</h1><div class="card"><div class="hero-top">${ring(overall)}<div class="grow"><b>Embarkation readiness</b><p class="muted">${escapeHTML(p.vessel)} · ${escapeHTML(p.joining||'Date not set')} · ${p.months} months</p></div></div><p class="muted">Progress is self-reported, not official clearance.</p><button class="btn secondary" id="editVoyage">Edit contract</button></div><div class="card">${sectionRow('requirements','Predeparture Requirements')}${sectionRow('packing','Packing Checklist')}${sectionRow('embarkation','Embarkation Folder')}${sectionRow('disembarkation','Disembarkation Folder')}</div><button class="btn secondary full" id="newVoyage">Prepare Another Contract</button>`}
function checklist(id){const p=state.voyage;const labels={requirements:'Predeparture Requirements',packing:'Packing Checklist',embarkation:'Embarkation Folder',disembarkation:'Disembarkation Folder'};return `<button class="back" data-open="voyage">← Voyage Ready</button><h1>${labels[id]}</h1><div class="card hero-top">${ring(progress(p[id]))}<div class="grow"><b>${p[id].filter(x=>x.done).length} completed</b><p class="muted">Mark items complete as you prepare.</p></div></div>${id==='packing'?`<div class="card"><label class="field">Contract duration: <span id="monthsLabel">${p.months} months</span><input id="months" type="range" min="1" max="12" value="${p.months}"></label><p class="muted">Suggested quantities are editable. Adjust for onboard supplies.</p></div>`:''}<div class="card">${p[id].map((x,i)=>`<div class="row"><input class="check" type="checkbox" data-check="${id}:${i}" ${x.done?'checked':''} aria-label="Complete ${escapeHTML(x.name)}"><span class="grow" style="${x.done?'text-decoration:line-through;color:#81938a':''}">${escapeHTML(x.name)}${x.na?'<small class="badge">N/A</small>':''}</span>${id==='packing'?`<div class="qty"><button data-qty="${i}:-1" aria-label="Reduce ${escapeHTML(x.name)}">−</button><b>${x.qty}</b><button data-qty="${i}:1" aria-label="Increase ${escapeHTML(x.name)}">+</button></div>`:`<button class="btn secondary" data-na="${id}:${i}">${x.na?'Restore':'N/A'}</button>`}<button data-remove="${id}:${i}" aria-label="Remove ${escapeHTML(x.name)}" style="border:0;background:none;color:#aa4c40">×</button></div>`).join('')}</div><button class="btn full" id="addItem">+ Add Custom Item</button>${id==='embarkation'||id==='disembarkation'?'<p class="muted">Document checklist only in this first build. Secure file attachments will be integrated with the existing Documents system.</p>':''}`}

/* Phase 1.7 — Learn UI. Existing learning engine stays in index.html. */
const learnCatalog=[
 {icon:'⚓',title:'OIC Examination',subtitle:'Deck and Engine · Operational level',tag:'Review & Exam',tone:'blue'},
 {icon:'▤',title:'OLP',subtitle:'Operational-level learning and practice',tag:'Study & Practice',tone:'violet'},
 {icon:'◈',title:'Deck',subtitle:'Navigation, cargo and watchkeeping',tag:'Study',tone:'blue'},
 {icon:'⚙',title:'Engine',subtitle:'Machinery, systems and watchkeeping',tag:'Study',tone:'green'},
 {icon:'✹',title:'Safety',subtitle:'LSA, FFE and shipboard safety',tag:'Study',tone:'amber'},
 {icon:'▣',title:'General',subtitle:'Maritime English and career preparation',tag:'Study',tone:'blue'}
];
function learn(){return `<div class="learn-page"><div class="learn-head"><h1>Learn</h1><p>Build your maritime knowledge, one session at a time.</p></div><section class="learn-progress card"><div class="learn-progress-top"><div><span class="learn-eyebrow">YOUR LEARNING PROGRESS</span><h2>Keep learning</h2><p>Progress will appear when existing learning records are connected.</p></div><div class="learn-progress-mark">—</div></div><div class="learn-progress-track"><span style="width:0"></span></div><small>No verified completion summary yet</small></section><div class="learn-mode" role="group" aria-label="Learning mode"><button type="button" class="selected" data-learn-mode="study" aria-pressed="true">Study</button><button type="button" data-learn-mode="exam" aria-pressed="false">Practice / Exam</button></div><div class="learn-section-title"><h2>Learning Library</h2><span>Existing Toolbox content</span></div><div class="learn-feature-grid">${learnCatalog.slice(0,2).map((c,i)=>`<button type="button" class="learn-feature ${c.tone}" data-learn-open="${i}"><span class="learn-feature-icon">${c.icon}</span><strong>${c.title}</strong><small>${c.subtitle}</small><span class="learn-feature-action">Open learning →</span></button>`).join('')}</div><div class="learn-section-title"><h2>Explore Topics</h2></div><div class="learn-topic-grid">${learnCatalog.slice(2).map((c,i)=>`<button type="button" class="learn-topic ${c.tone}" data-learn-open="${i+2}"><span class="learn-topic-icon">${c.icon}</span><strong>${c.title}</strong><small>${c.subtitle}</small></button>`).join('')}</div><div class="learn-info card"><strong>Existing learning materials are preserved</strong><p>OIC, OLP and other available modules currently run in the original Toolbox learning engine. Open a category to continue there; scores and progress are not fabricated on this screen.</p><a href="index.html" class="btn full learn-legacy-link">Open existing Toolbox learning →</a></div></div>`}
function learnOpen(index){const item=learnCatalog[index];if(!item)return;openModal(`<h2>${escapeHTML(item.title)}</h2><p class="muted">${escapeHTML(item.subtitle)}</p><p>Continue using the existing Toolbox learning module. The new Learn screen is a navigation layer; direct deep links and progress synchronization will follow after the original learning routes are verified.</p><a class="btn full learn-legacy-link" href="index.html">Open Toolbox Learning →</a>`)}

const documentSections=[
 ['personal','Personal Documents','Passport, Seaman’s Book, visas','▣'],
 ['certificates','Maritime Certificates','STCW, licenses and endorsements','⚓'],
 ['medical','Medical Documents','PEME and medical records','✚'],
 ['sea-service','Sea Service Records','Vessels, ranks and sign-on / sign-off','▤']
];
const quickIdTypes=[['passport','Passport Number'],['seamans','Seaman’s Book Number'],['sss','SSS Number'],['pagibig','Pag-IBIG MID'],['philhealth','PhilHealth PIN'],['tin','TIN'],['marina','MARINA SRN'],['other','Other Identification']];
function documents(){return `<div class="docs-page"><div class="docs-head"><h1>Documents</h1><p>Your maritime records in one place.</p></div><div class="docs-status"><div class="docs-status-tile valid"><b>—</b><span>Valid</span></div><div class="docs-status-tile soon"><b>—</b><span>Expiring Soon</span></div><div class="docs-status-tile expired"><b>—</b><span>Expired</span></div></div><p class="docs-note">Document counts will appear after your existing records are securely connected. No sample data is shown.</p><div class="docs-section-title"><h2>My Documents</h2></div><div class="docs-links">${documentSections.map(([id,title,subtitle,icon])=>`<button class="docs-link" data-doc-section="${id}"><span class="docs-link-icon">${icon}</span><span><strong>${title}</strong><small>${subtitle}</small></span><span class="docs-arrow">›</span></button>`).join('')}<button class="docs-link" data-doc-section="cv"><span class="docs-link-icon">▤</span><span><strong>Generate Maritime CV</strong><small>Create and export your maritime CV</small></span><span class="docs-arrow">›</span></button></div><div class="docs-section-title"><h2>Quick ID Cards</h2><span>Fast reference for forms</span></div><p class="docs-note">Your ID numbers are hidden until a secure document connection is available.</p><div class="quick-id-grid">${quickIdTypes.map(([id,label])=>`<button class="quick-id" data-quick-id="${id}"><span class="quick-id-symbol">▣</span><strong>${label}</strong><span>Not connected</span><small>View details ›</small></button>`).join('')}</div><div class="docs-privacy">🔒 Identification numbers are not saved in this preview. Secure storage, reveal, and copy actions will be enabled after integration.</div><a class="btn full docs-original" href="index.html">Open existing Toolbox Documents →</a></div>`}
function documentSectionPage(id){const item=documentSections.find(x=>x[0]===id);const title=id==='cv'?'Maritime CV':item?.[1];if(!title)return documents();return `<button class="back" data-open="documents">← Documents</button><div class="docs-head"><h1>${title}</h1><p>Access your existing Toolbox records while secure integration is being completed.</p></div><div class="card docs-interim"><strong>Existing feature preserved</strong><p class="muted">The redesigned document interface is not yet connected to your existing document records. Continue in the original Toolbox application. No new identification data is stored here.</p><a class="btn full docs-original" href="index.html">Open existing Toolbox →</a></div>`}
function quickIdDetail(id){const item=quickIdTypes.find(x=>x[0]===id);if(!item)return;openModal(`<h2>${escapeHTML(item[1])}</h2><p class="muted">No secure ID record is connected yet.</p><p>For your privacy, this preview does not collect, store, or copy identification numbers. Once connected to secure storage, this card will support masked display, reveal, and copy.</p><button type="button" class="btn secondary full" id="closeQuickId">Close</button>`)}
function legacy(title,description){return `<h1>${title}</h1><p class="muted">${description}</p><div class="card"><h3>Existing Toolbox modules</h3><p>Access the original working app while we migrate its features into the new design.</p><a class="btn" style="display:inline-block;text-decoration:none" href="index.html">Open existing Toolbox →</a></div>`}
function render(){let page=state.page;document.getElementById('view').innerHTML=page==='home'?home():page.startsWith('directory-')?directoryPage(Number(page.split('-')[1])):page==='voyage'?voyage():['requirements','packing','embarkation','disembarkation'].includes(page)&&state.voyage?checklist(page):page==='learn'?learn():page==='documents'?documents():page.startsWith('doc-')?documentSectionPage(page.slice(4)):legacy('Account','Profile, security, settings, and help.');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));}
function openModal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').showModal()}
function closeModal(){document.getElementById('modal').close()}
document.addEventListener('click',e=>{if(e.target.id==='closeQuickId'){closeModal();return}const qid=e.target.closest('[data-quick-id]');if(qid){quickIdDetail(qid.dataset.quickId);return}const docsection=e.target.closest('[data-doc-section]');if(docsection){state.tab='documents';navigate('doc-'+docsection.dataset.docSection);return}const learnItem=e.target.closest('[data-learn-open]');if(learnItem){learnOpen(Number(learnItem.dataset.learnOpen));return}const learnMode=e.target.closest('[data-learn-mode]');if(learnMode){document.querySelectorAll('[data-learn-mode]').forEach(b=>{const active=b===learnMode;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.learn-feature-action').forEach(x=>x.textContent=learnMode.dataset.learnMode==='exam'?'Open practice / exam →':'Open learning →');return}const rating=e.target.closest('[data-rating]');if(rating){localStorage.setItem('toolbox2-feedback-rating',rating.dataset.rating);render();return}const tab=e.target.closest('[data-tab]');if(tab){if(tab.dataset.tab==='create'){openModal(`<h2>Quick Create</h2><div class="row" data-action="new">New Voyage Checklist →</div><div class="row" data-action="document">Add Document →</div><div class="row" data-action="cv">Create Maritime CV →</div>`);return}state.tab=tab.dataset.tab;navigate(state.tab);return}const svc=e.target.closest('[data-service]');if(svc){const [g,i]=svc.dataset.service.split(':').map(Number);serviceDialog(g,i);return}const directory=e.target.closest('[data-directory]');if(directory){state.tab='home';navigate('directory-'+directory.dataset.directory);return}const link=e.target.closest('[data-link]');if(link){window.open(link.dataset.link,'_blank','noopener,noreferrer');return}const open=e.target.closest('[data-open]');if(open){navigate(open.dataset.open);return}const act=e.target.closest('[data-action]');if(act){closeModal();if(act.dataset.action==='new')navigate('voyage');else window.location.href='index.html';return}if(e.target.id==='startVoyage'){const months=+document.getElementById('months').value;state.voyage={vessel:document.getElementById('vessel').value.trim()||'Next Voyage',joining:document.getElementById('joining').value,months,...Object.fromEntries(Object.entries(defaults).map(([k,items])=>[k,items.map(([name,value])=>k==='packing'?{name,qty:Math.max(1,Math.ceil(value*months/6)),base:value,custom:false,done:false}:{name,done:value,na:false})]))};save();navigate('voyage');return}if(e.target.id==='editVoyage'){const p=state.voyage;openModal(`<h2>Edit Contract</h2><label class="field">Vessel<input id="editVessel" value="${escapeHTML(p.vessel)}"></label><label class="field">Joining date<input type="date" id="editDate" value="${escapeHTML(p.joining)}"></label><button class="btn full" id="saveContract">Save</button>`);return}if(e.target.id==='saveContract'){state.voyage.vessel=document.getElementById('editVessel').value;state.voyage.joining=document.getElementById('editDate').value;save();closeModal();render();return}if(e.target.id==='newVoyage'){openModal(`<h2>Start another voyage?</h2><p>This will replace the current local checklist. Export or back up any details you need first.</p><button class="btn full" id="confirmNew">Replace Checklist</button>`);return}if(e.target.id==='confirmNew'){state.voyage=null;save();closeModal();navigate('voyage');return}if(e.target.id==='addItem'){openModal(`<h2>Add checklist item</h2><label class="field">Item name<input id="itemName" maxlength="100"></label><button class="btn full" id="saveItem">Add item</button>`);return}if(e.target.id==='saveItem'){const name=document.getElementById('itemName').value.trim();if(!name)return;const id=state.page;state.voyage[id].push(id==='packing'?{name,qty:1,done:false}:{name,done:false,na:false});save();closeModal();render();return}for(const attr of ['qty','na','remove']){const b=e.target.closest(`[data-${attr}]`);if(!b)continue;const [a,c]=b.dataset[attr].split(':');const id=attr==='qty'?state.page:a;const i=attr==='qty'?+a:+c;if(attr==='qty'){state.voyage[id][i].qty=Math.max(0,state.voyage[id][i].qty+(+c));state.voyage[id][i].custom=true;}if(attr==='na')state.voyage[id][i].na=!state.voyage[id][i].na;if(attr==='remove')state.voyage[id].splice(i,1);save();render();return}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){const [id,i]=e.target.dataset.check.split(':');state.voyage[id][+i].done=e.target.checked;save();render()}if(e.target.id==='months'&&state.voyage){state.voyage.months=+e.target.value;state.voyage.packing.forEach(item=>{if(!item.custom&&item.base)item.qty=Math.max(1,Math.ceil(item.base*state.voyage.months/6))});save();render()}});
document.addEventListener('input',e=>{if(e.target.id==='months'){document.getElementById('monthsLabel').textContent=`${e.target.value} months`}if(e.target.id==='search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.category-tile').forEach(b=>{const gi=Number(b.dataset.directory);b.hidden=!!q&&!serviceGroups[gi].title.toLowerCase().includes(q)&&!serviceGroups[gi].items.some(x=>x[0].toLowerCase().includes(q))})}if(e.target.id==='directorySearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('.service-list-card').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(q)})}});
document.getElementById('alerts').addEventListener('click',()=>openModal('<h2>Reminders</h2><p>Notifications will be added after the checklist and document systems are integrated.</p>'));
